22:test('buildUrl encodes existing escaped path segments once', () => {
32:test('serializeQuery supports arrays, dates, and object payloads', () => {
33:  const query = _private.serializeQuery({
46:test('buildUrl keeps retry=0 and include_archived=false query values', () => {
59:test('serializeQuery keeps 0 and false items inside array values', () => {
60:  const query = _private.serializeQuery({ retry: [0, 1], flag: [false, true] });
65:test('serializeQuery still omits null, undefined, and empty-string values', () => {
66:  const query = _private.serializeQuery({
77:test('buildSignedUrl appends a deterministic signature', () => {
90:test('redactUrl redacts redirect-like query keys', () => {
96:test('parseRetryAfter accepts seconds, HTTP dates, and invalid values', () => {
104:test('isSafeRedirect allows only configured hosts and http protocols', () => {
});

test('parseRetryAfter accepts seconds, HTTP dates, and invalid values', () => {
  const now = new Date('2026-01-01T00:00:00.000Z');

  assert.equal(parseRetryAfter('60', now).toISOString(), '2026-01-01T00:01:00.000Z');
  assert.equal(parseRetryAfter('Wed, 21 Oct 2026 07:28:00 GMT').toISOString(), '2026-10-21T07:28:00.000Z');
  assert.equal(parseRetryAfter('not a date', now), null);
});

test('isSafeRedirect allows only configured hosts and http protocols', () => {
  assert.equal(isSafeRedirect('https://app.example.test/home', ['app.example.test']), true);
  assert.equal(isSafeRedirect('javascript:alert(1)', ['app.example.test']), false);
  assert.equal(isSafeRedirect('https://evil.example.test/home', ['app.example.test']), false);
});

